#include "ClipboardLiveProtocol.h"
#include "ContentModel.h"
#include <sodium.h>
#include <algorithm>
#include <set>
#include <limits>
namespace private_input::activity {namespace {
constexpr uint64_t MaxCursor=uint64_t(INT64_MAX),Lease=2592000,TTL=600;
Data raw(const Id&v){return {v.begin(),v.end()};}Data raw(const Key&v){return {v.begin(),v.end()};}
Data prefix(const char*label){auto d=bytes(label);d.push_back(0);d.push_back(1);return d;}
void shape(const Json&j,std::initializer_list<const char*>keys){require(j.kind==Json::Kind::object&&j.fields.size()==keys.size(),"live object shape");for(auto key:keys)require(j.has(key),"live field missing");}
void version(const Json&j){require(j.at("version").num()==1,"live version");}
void life(const Json&j,uint64_t maximum){auto a=j.at("issuedAt").num(),b=j.at("expiresAt").num();require(a<=MaxCursor&&b<=MaxCursor&&b>a&&b-a<=maximum,"live lifetime");}
void clock(const Json&j,uint64_t now){auto a=j.at("issuedAt").num(),b=j.at("expiresAt").num();require(now<b&&(a<=now||a-now<=300),"live expired or future");}
Key key(const Json&j){auto data=unbase64(j.str(),32);Key out;std::copy(data.begin(),data.end(),out.begin());return out;}
void verify(const Data&data,const Json&signature,const Key&pub){auto sig=unbase64(signature.str(),64);require(crypto_sign_verify_detached(sig.data(),data.data(),data.size(),pub.data())==0,"live signature rejected");}
Key derive(const Key&source,const Data&salt,const Data&info){Key prk{},out{};require(crypto_kdf_hkdf_sha256_extract(prk.data(),salt.data(),salt.size(),source.data(),source.size())==0,"live HKDF extract");auto rc=crypto_kdf_hkdf_sha256_expand(out.data(),32,reinterpret_cast<const char*>(info.data()),info.size(),prk.data());sodium_memzero(prk.data(),prk.size());require(rc==0,"live HKDF expand");return out;}
const ClipboardLiveMember&member(const ClipboardLiveGrant&g,const Id&id){auto at=g.members.find(id);require(at!=g.members.end(),"live sender not permitted");return at->second;}
Key validateCertificate(const Json&cert,const ClipboardLiveGrant&grant,uint64_t now,const Id&parent){auto canonical=clipboardLiveCertificateBytes(cert);require(parseId(cert.at("group").str())==grant.group&&parseId(cert.at("parent").str())==parent&&cert.at("epoch").num()==grant.epoch,"live certificate scope");clock(cert,now);auto&sender=member(grant,parent);require(key(cert.at("signingPublic"))==sender.signingPublic,"live primary key mismatch");verify(canonical,cert.at("signature"),sender.signingPublic);return key(cert.at("delegatePublic"));}
void text(const std::string&value){validateUtf8(value);require(!value.empty()&&value.size()<=65536&&value.find('\0')==std::string::npos,"live text limit");}
}
ClipboardLiveGrant::~ClipboardLiveGrant(){sodium_memzero(delegateSeed.data(),delegateSeed.size());for(auto&item:members)sodium_memzero(item.second.senderKey.data(),32);}
Data clipboardLiveCertificateBytes(const Json&j){shape(j,{"version","group","parent","epoch","generation","signingPublic","delegatePublic","issuedAt","expiresAt","signature"});version(j);life(j,Lease);require(j.at("epoch").num()>0,"live epoch");auto d=prefix("PrivateInput/clipboard-live-certificate/v1");append(d,raw(parseId(j.at("group").str())));append(d,raw(parseId(j.at("parent").str())));be64(d,j.at("epoch").num());append(d,raw(parseId(j.at("generation").str())));append(d,unbase64(j.at("signingPublic").str(),32));append(d,unbase64(j.at("delegatePublic").str(),32));be64(d,j.at("issuedAt").num());be64(d,j.at("expiresAt").num());return d;}
Key clipboardLiveCertificateDigest(const Json&j){auto d=clipboardLiveCertificateBytes(j);append(d,unbase64(j.at("signature").str(),64));return sha256(d);}
Data clipboardLiveEventHeader(const Json&j){shape(j,{"version","group","sender","event","epoch","issuedAt","expiresAt","nonce","ciphertext","certificate","signature"});version(j);life(j,TTL);require(j.at("epoch").num()>0,"live epoch");auto cipher=unbase64(j.at("ciphertext").str());require(cipher.size()>=16&&cipher.size()<=65552,"live cipher bound");auto d=prefix("PrivateInput/clipboard-live-event/v1");append(d,raw(parseId(j.at("group").str())));append(d,raw(parseId(j.at("sender").str())));append(d,raw(parseId(j.at("event").str())));be64(d,j.at("epoch").num());be64(d,j.at("issuedAt").num());be64(d,j.at("expiresAt").num());append(d,unbase64(j.at("nonce").str(),12));append(d,raw(clipboardLiveCertificateDigest(j.at("certificate"))));return d;}
Data clipboardLiveRequestHeader(const Json&j){shape(j,{"version","group","sender","epoch","nonce","issuedAt","certificate","body","signature"});version(j);require(j.at("epoch").num()>0&&j.at("issuedAt").num()<=MaxCursor,"live request bounds");auto body=unbase64(j.at("body").str());require(!body.empty()&&body.size()<=131072,"live request body bound");auto d=prefix("PrivateInput/clipboard-live-request/v1");append(d,raw(parseId(j.at("group").str())));append(d,raw(parseId(j.at("sender").str())));be64(d,j.at("epoch").num());append(d,raw(parseId(j.at("nonce").str())));be64(d,j.at("issuedAt").num());append(d,raw(clipboardLiveCertificateDigest(j.at("certificate"))));append(d,raw(sha256(body)));return d;}
Data clipboardLiveRevokeHeader(const Json&j){shape(j,{"version","group","parent","epoch","generation","issuedAt","nonce","signature"});version(j);require(j.at("epoch").num()>0&&j.at("issuedAt").num()<=MaxCursor,"live revoke bounds");auto d=prefix("PrivateInput/clipboard-live-revoke/v1");append(d,raw(parseId(j.at("group").str())));append(d,raw(parseId(j.at("parent").str())));be64(d,j.at("epoch").num());append(d,raw(parseId(j.at("generation").str())));be64(d,j.at("issuedAt").num());append(d,raw(parseId(j.at("nonce").str())));return d;}
Key clipboardSenderKey(const Key&master,const Id&group,uint64_t epoch,const Id&sender,const Key&pub){auto salt=raw(group);be64(salt,epoch);auto info=bytes("PrivateInput/sender-domain-key/v1");info.push_back(0);append(info,raw(sender));append(info,raw(pub));info.push_back(2);return derive(master,salt,info);}
Key clipboardLiveKey(const Key&source,const Id&group,uint64_t epoch,const Id&sender,const Key&pub){auto salt=raw(group);be64(salt,epoch);auto info=bytes("PrivateInput/clipboard-live-key/v1");info.push_back(0);append(info,raw(sender));append(info,raw(pub));return derive(source,salt,info);}
Json ClipboardLiveGrant::encode()const{auto rows=Json::array();for(const auto&entry:members)rows.items.push_back(Json::object({{"device",uuidText(entry.first)},{"signingPublic",base64(raw(entry.second.signingPublic))},{"senderKey",base64(raw(entry.second.senderKey))}}));return Json::object({{"version",1},{"group",uuidText(group)},{"parent",uuidText(parent)},{"epoch",epoch},{"generation",uuidText(generation)},{"endpoint",endpoint},{"scope",scope},{"personal",personal},{"certificate",certificate},{"delegateSeed",base64(raw(delegateSeed))},{"members",rows}});}
ClipboardLiveGrant ClipboardLiveGrant::decode(const Json&j,uint64_t now){shape(j,{"version","group","parent","epoch","generation","endpoint","scope","personal","certificate","delegateSeed","members"});version(j);ClipboardLiveGrant out;out.group=parseId(j.at("group").str());out.parent=parseId(j.at("parent").str());out.generation=parseId(j.at("generation").str());out.epoch=j.at("epoch").num();out.endpoint=j.at("endpoint").str();out.scope=j.at("scope").str();out.personal=j.at("personal").str();out.certificate=j.at("certificate");out.delegateSeed=key(j.at("delegateSeed"));require(out.epoch>0&&!out.endpoint.empty()&&!out.scope.empty()&&out.scope.size()<=512,"live grant bounds");(void)parseId(out.personal);auto&rows=j.at("members");require(rows.kind==Json::Kind::array&&!rows.items.empty()&&rows.items.size()<=64,"live member bound");for(const auto&r:rows.items){shape(r,{"device","signingPublic","senderKey"});require(out.members.emplace(parseId(r.at("device").str()),ClipboardLiveMember{key(r.at("signingPublic")),key(r.at("senderKey"))}).second,"live duplicate member");}auto delegate=validateCertificate(out.certificate,out,now,out.parent);require(delegate==publicKey(out.delegateSeed)&&parseId(out.certificate.at("generation").str())==out.generation,"live delegated key mismatch");return out;}
ClipboardLiveGrant issueClipboardLiveGrant(const GroupIdentity&i,const protocol::VerifiedMembership&m,const Key&master,const std::string&endpoint,const std::string&scope,const std::string&personal,uint64_t issued){require(sodium_init()>=0&&issued<=MaxCursor-Lease,"live grant time");auto trust=m.trust(protocol::MembershipDomain::clipboard);auto me=trust.members.find(i.device);require(me!=trust.members.end()&&me->second==publicKey(i.signingSeed),"live grant parent permission");ClipboardLiveGrant out;out.group=trust.group;out.epoch=trust.epoch;out.parent=i.device;out.generation=newId();out.endpoint=endpoint;out.scope=scope;out.personal=personal;randombytes_buf(out.delegateSeed.data(),32);for(const auto&entry:trust.members)out.members.emplace(entry.first,ClipboardLiveMember{entry.second,clipboardSenderKey(master,out.group,out.epoch,entry.first,entry.second)});out.certificate=Json::object({{"version",1},{"group",uuidText(out.group)},{"parent",uuidText(out.parent)},{"epoch",out.epoch},{"generation",uuidText(out.generation)},{"signingPublic",base64(raw(me->second))},{"delegatePublic",base64(raw(publicKey(out.delegateSeed)))},{"issuedAt",issued},{"expiresAt",issued+Lease},{"signature",""}});out.certificate["signature"]=base64(sign(clipboardLiveCertificateBytes(out.certificate),i.signingSeed));return out;}
Json sealClipboardLive(const ClipboardLiveGrant&g,const std::string&value,uint64_t now,const Id&event,const Data&provided){text(value);require(now<=MaxCursor-TTL&&now<g.certificate.at("expiresAt").num(),"live publish expiry");auto nonce=provided;if(nonce.empty()){nonce.resize(12);randombytes_buf(nonce.data(),nonce.size());}require(nonce.size()==12,"live nonce");auto expiry=std::min(now+TTL,g.certificate.at("expiresAt").num());auto j=Json::object({{"version",1},{"group",uuidText(g.group)},{"sender",uuidText(g.parent)},{"event",uuidText(event)},{"epoch",g.epoch},{"issuedAt",now},{"expiresAt",expiry},{"nonce",base64(nonce)},{"ciphertext",base64(Data(16,0))},{"certificate",g.certificate},{"signature",""}});auto aad=clipboardLiveEventHeader(j);auto&own=member(g,g.parent);auto derived=clipboardLiveKey(own.senderKey,g.group,g.epoch,g.parent,own.signingPublic);Data cipher(value.size()+16);unsigned long long count=0;auto rc=crypto_aead_chacha20poly1305_ietf_encrypt(cipher.data(),&count,reinterpret_cast<const unsigned char*>(value.data()),value.size(),aad.data(),aad.size(),nullptr,nonce.data(),derived.data());sodium_memzero(derived.data(),32);require(rc==0&&count==cipher.size(),"live encryption");j["ciphertext"]=base64(cipher);append(aad,cipher);j["signature"]=base64(sign(aad,g.delegateSeed));return j;}
Json clipboardLiveRequest(const ClipboardLiveGrant&g,uint64_t after,const Json&publish,uint64_t now,const Id&nonce){require(after<=MaxCursor&&now<=MaxCursor,"live request cursor");auto body=bytes(Json::object({{"after",after},{"limit",32},{"publish",publish}}).dump());auto j=Json::object({{"version",1},{"group",uuidText(g.group)},{"sender",uuidText(g.parent)},{"epoch",g.epoch},{"nonce",uuidText(nonce)},{"issuedAt",now},{"certificate",g.certificate},{"body",base64(body)},{"signature",""}});j["signature"]=base64(sign(clipboardLiveRequestHeader(j),g.delegateSeed));return j;}
Json clipboardLiveRevoke(const Json&cert,const Key&seed,uint64_t now,const Id&nonce){require(publicKey(seed)==key(cert.at("signingPublic")),"live revoke primary key");auto j=Json::object({{"version",1},{"group",cert.at("group")},{"parent",cert.at("parent")},{"epoch",cert.at("epoch")},{"generation",cert.at("generation")},{"issuedAt",now},{"nonce",uuidText(nonce)},{"signature",""}});j["signature"]=base64(sign(clipboardLiveRevokeHeader(j),seed));return j;}
ClipboardLiveOpened openClipboardProjection(const std::string&kind,const Json&j,const ClipboardLiveGrant&g,uint64_t now){ClipboardLiveOpened out;out.kind=kind;out.group=parseId(j.at("group").str());out.sender=parseId(j.at("sender").str());out.event=parseId(j.at("event").str());out.epoch=j.at("epoch").num();out.issuedAt=j.at("issuedAt").num();out.expiresAt=j.at("expiresAt").num();require(out.group==g.group&&out.epoch==g.epoch,"live event scope");auto&sender=member(g,out.sender);Data aad,cipher,nonce;Key derived{};if(kind=="live"){aad=clipboardLiveEventHeader(j);auto pub=validateCertificate(j.at("certificate"),g,now,out.sender);require(out.expiresAt<=j.at("certificate").at("expiresAt").num(),"live event certificate expiry");cipher=unbase64(j.at("ciphertext").str());auto signedData=aad;append(signedData,cipher);verify(signedData,j.at("signature"),pub);nonce=unbase64(j.at("nonce").str(),12);derived=clipboardLiveKey(sender.senderKey,g.group,g.epoch,out.sender,sender.signingPublic);}else {require(kind=="legacy","live item kind");shape(j,{"version","group","sender","event","epoch","sequence","domain","issuedAt","expiresAt","ciphertext","signature"});auto e=decodeContentEnvelope(j);require(e.domain==2,"live projection domain");aad=protocol::header(e);cipher=e.ciphertext;auto signedData=aad;append(signedData,cipher);verify(signedData,j.at("signature"),sender.signingPublic);nonce=Data(4,0);be64(nonce,e.sequence);derived=sender.senderKey;}life(j,TTL);clock(j,now);require(cipher.size()>=16&&cipher.size()<=65552,"live decrypt bounds");Data clear(cipher.size()-16);unsigned long long count=0;auto rc=crypto_aead_chacha20poly1305_ietf_decrypt(clear.data(),&count,nullptr,cipher.data(),cipher.size(),aad.data(),aad.size(),nonce.data(),derived.data());sodium_memzero(derived.data(),32);require(rc==0&&count==clear.size(),"live decrypt");out.text=std::string(clear.begin(),clear.end());text(out.text);auto signedData=aad;append(signedData,cipher);append(signedData,unbase64(j.at("signature").str(),64));out.digest=base64(raw(sha256(signedData)));return out;}
void validateClipboardLiveResponse(const Json&r,uint64_t after,const Json&published){shape(r,{"version","accepted","head","next","items"});version(r);auto head=r.at("head").num(),next=r.at("next").num();require(head<=MaxCursor&&next>=after&&next<=head&&after<=head,"live cursor order");if(published.kind==Json::Kind::null)require(r.at("accepted").kind==Json::Kind::null,"unexpected live acceptance");else require(parseId(r.at("accepted").str())==parseId(published.at("event").str()),"live acceptance mismatch");auto&rows=r.at("items");require(rows.kind==Json::Kind::array&&rows.items.size()<=32&&r.dump().size()<=1048576,"live response bounds");uint64_t previous=after;for(const auto&row:rows.items){shape(row,{"cursor","kind","wire"});auto cursor=row.at("cursor").num();require(cursor>previous&&cursor<=next,"live item order");previous=cursor;require(row.at("kind").str()=="legacy"||row.at("kind").str()=="live","live item type");require(unbase64(row.at("wire").str()).size()<=131072,"live wire bound");}require(next>after||next==head,"live cursor stalled");}
}
